parameterdescription.para:
出力バッファに書き込まれた長さを記憶するポインタの概要。 Example intret;

bytesharedKey[32];
word32keySz;

curve25519_keyprivKey,pubKey;
//initializebothkeys

ret=wc_curve25519_shared_secret_ex(&privKey,&pubKey,sharedKey,&keySz,
EC25519_BIG_ENDIAN);
if(ret!=0){
//errorgeneratingsharedkey
}

simplesect.para:
BAD_FUNC_ARG キーがNULLのときに返されます。 Example curve25519_keykey;
wc_curve25519_init(&key);//initializekey
//makekeyandproceedtoencryption

parameterdescription.para:
OUTでは、出力バッファに書き込まれたバイトを保存します。 Example intret;

bytepriv[32];
intprivSz;
curve25519_keykey;
//initializeandmakekey
ret=wc_curve25519_export_private_raw_ex(&key,priv,&privSz,
EC25519_BIG_ENDIAN);
if(ret!=0){
//errorexportingkey
}

OUTでは、出力バッファに書き込まれたバイトを保存します。 Example intret;

bytepub[32];
intpubSz;

curve25519_keykey;
//initializeandmakekey

ret=wc_curve25519_export_public_ex(&key,pub,&pubSz,EC25519_BIG_ENDIAN);
if(ret!=0){
//errorexportingkey
}

ON INは、パブバッファのサイズをバイト単位で）です。ON OUTでは、PUBバッファに書き込まれたバイトを保存します。 Example intret;

bytepub[32];
bytepriv[32];
intpubSz;
intprivSz;

curve25519_keykey;
//initializeandmakekey

ret=wc_curve25519_export_key_raw_ex(&key,priv,&privSz,pub,&pubSz,
EC25519_BIG_ENDIAN);
if(ret!=0){
//errorexportingkey
}

simplesect.para:
0 キーがNULLの場合は返されます Example intkeySz;

curve25519_keykey;
//initializeandmakekey

keySz=wc_curve25519_size(&key);
